from langflow.custom import Component
from langflow.schema import Data
from collections import defaultdict
from typing import List, Dict, Any

class ParseDataComponent(Component):
    display_name = "Query Deduplication"
    description = "Deduplicate the queries by (system, query)"
    icon = "braces"
    name = "ParseData"


    inputs = [
        DataInput(name="data", display_name="Data", info="The data to process."),
    ]

    outputs = [
        Output(display_name="Output", name="output", method="parse_data"),
    ]

    def parse_data(self) -> Data:
        rows = self.data.rows
        customer_id = self.data.customer_id
        customer_question = self.data.customer_question

        deduplicated_queries = defaultdict(lambda: {
            'instruction': set(), 'system': None, 'query': None
        })

        # Deduplicate by (system, query)
        for row in rows:
            compound_key = (row['system'].lower(), row['query'].lower())

            # Initialize system and query if first occurrence
            if deduplicated_queries[compound_key]['query'] is None:
                deduplicated_queries[compound_key]['query'] = row['query']
            if deduplicated_queries[compound_key]['system'] is None:
                deduplicated_queries[compound_key]['system'] = row['system']

            # Add instructions to set to ensure uniqueness
            for instruction in row['instruction']:
                deduplicated_queries[compound_key]['instruction'].add(instruction)

        # Convert deduplicated data to the required format
        final_docs = [
            {
                'system': instruction_info['system'],
                'query': instruction_info['query'],
                'instruction': list(instruction_info['instruction']),  # Convert set to list
            }
            for instruction_info in deduplicated_queries.values()
        ]

        # Return deduplicated data as a new Data object
        new_obj = Data(customer_id=customer_id, customer_question=customer_question, rows=final_docs)
        self.status = new_obj
        return new_obj

