from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from langflow.schema import Data


class CustomComponent(Component):
    display_name = "Chat History Deduplication"
    description = "Deduplicate chat history by matching text."
    documentation: str = "http://docs.langflow.org/components/custom"
    icon = "custom_components"
    name = "CustomComponent"

    inputs = [
        DataInput(name="input_value", display_name="Input Value", value="Hello, World!"),
    ]

    outputs = [
        Output(display_name="Output", name="output", method="build_output"),
    ]

    def deduplicate_by_text(self, objects: List[Data]) -> List[Data]:
        deduped_dict = {}
        for obj in objects:
            if obj.text not in deduped_dict or deduped_dict[obj.text].timestamp < obj.timestamp:
                deduped_dict[obj.text] = obj
        return list(deduped_dict.values())


    def build_output(self) -> Data:
        deduplicated_data = self.deduplicate_by_text(self.input_value)
        for obj in deduplicated_data:
            print(f"Text: {obj.text}, Timestamp: {obj.timestamp}")

        self.status = deduplicated_data
        return deduplicated_data

import asyncio
import json
from typing import Any, List, Optional
from urllib.parse import parse_qsl, urlencode, urlparse, urlunparse

import httpx
from loguru import logger

from langflow.base.curl.parse import parse_context
from langflow.custom import Component
from langflow.io import DataInput, DropdownInput, IntInput, MessageTextInput, NestedDictInput, Output
from langflow.schema import Data
from langflow.schema.dotdict import dotdict


class APIRequestComponent(Component):
    display_name = "API Request"
    description = (
        "This component allows you to make HTTP requests to one or more URLs. "
        "You can provide headers and body as either dictionaries or Data objects. "
        "Additionally, you can append query parameters to the URLs.\n\n"
        "**Note:** Check advanced options for more settings."
    )
    icon = "Globe"
    name = "APIRequest"

    inputs = [
        StrInput(
            name="url",
            display_name="URL",
            info="URL input",
        ),
        MessageTextInput(
            name="curl",
            display_name="Curl",
            info="Paste a curl command to populate the fields. This will fill in the dictionary fields for headers and body.",
            advanced=False,
            refresh_button=True,
        ),
        DropdownInput(
            name="method",
            display_name="Method",
            options=["GET", "POST", "PATCH", "PUT"],
            value="GET",
            info="The HTTP method to use (GET, POST, PATCH, PUT).",
        ),
        DataInput(
            name="data_objects",
            display_name="Data Objects",
            info="List of transformed Data objects to use as request payloads.",
        ),
        IntInput(
            name="timeout",
            display_name="Timeout",
            value=5,
            info="The timeout to use for the request.",
        ),
        StrInput(
            name="lsl_key",
            display_name="lsl_key",
            info="lsl_key for header",
        ),
        StrInput(
            name="api_key",
            display_name="api_key",
            info="api_key for header",
        )
    ]

    outputs = [
        Output(display_name="Data", name="data", method="make_requests"),
    ]

    def parse_curl(self, curl: str, build_config: dotdict) -> dotdict:
        try:
            parsed = parse_context(curl)
            build_config["urls"]["value"] = [parsed.url]
            build_config["method"]["value"] = parsed.method.upper()
            build_config["headers"]["value"] = dict(parsed.headers)

            if parsed.data:
                try:
                    json_data = json.loads(parsed.data)
                    build_config["body"]["value"] = json_data
                except json.JSONDecodeError as e:
                    logger.error(f"Error decoding JSON data: {e}")
            else:
                build_config["body"]["value"] = {}
        except Exception as exc:
            logger.error(f"Error parsing curl: {exc}")
            raise ValueError(f"Error parsing curl: {exc}")
        return build_config

    def update_build_config(self, build_config: dotdict, field_value: Any, field_name: Optional[str] = None):
        if field_name == "curl" and field_value:
            build_config = self.parse_curl(field_value, build_config)
        return build_config

    async def make_request(
        self,
        client: httpx.AsyncClient,
        method: str,
        url: str,
        headers: Optional[dict] = None,
        body: Optional[dict] = None,
        timeout: int = 5,
    ) -> Data:
        try:
            response = await client.request(method, url, headers=headers, json=body, timeout=timeout)
            try:
                result = response.json()
            except Exception:
                result = response.text
            return Data(
                data={
                    "source": url,
                    "headers": headers,
                    "status_code": response.status_code,
                    "result": result,
                },
            )
        except httpx.TimeoutException:
            return Data(
                data={
                    "source": url,
                    "headers": headers,
                    "status_code": 408,
                    "error": "Request timed out",
                },
            )
        except Exception as exc:
            return Data(
                data={
                    "source": url,
                    "headers": headers,
                    "status_code": 500,
                    "error": str(exc),
                },
            )

    def add_query_params(self, url: str, params: dict) -> str:
        url_parts = list(urlparse(url))
        query = dict(parse_qsl(url_parts[4]))
        query.update(params)
        url_parts[4] = urlencode(query)
        return urlunparse(url_parts)

    async def make_requests(self) -> List[Data]:
        method = self.method
        url = self.url
        headers = Data(**{
                            'api_key': self.api_key,
                            'lsl_key': self.lsl_key,
                            'channel_id': 'MRMUI',
                            'Content-Type': 'application/json'
                        }).data
        timeout = self.timeout

        # Ensure data_objects is a list and access the rows properly
        if isinstance(self.data_objects, Data):
            data_rows = self.data_objects.rows  # Access rows in the Data object
        else:
            raise TypeError("Expected data_objects to be of type Data with a 'rows' attribute")

        # Print each data row to verify the contents
        print("HTTP request data objects:")
        for data_obj in data_rows:
            print(f"data_obj is: {data_obj}")

        async with httpx.AsyncClient() as client:
            results = await asyncio.gather(
                *[
                    self.make_request(
                        client,
                        method,
                        self.add_query_params(url, {"query": data_obj["query"]}),
                        headers=headers,
                        body={
                            "mfaType": "8",
                            "opCode": "0",
                            "customerQuestion": self.data_objects.customer_question,
                            "customerKey": [self.data_objects.customer_id],
                            "queries": [data_obj["query"]],
                        },
                        timeout=timeout,
                    )
                    for data_obj in data_rows
                ]
            )
        # Post-process results to match the desired output format
        formatted_results = []
        for result in results:
            # Extract only the required fields from each result's data
            if "result" in result.data and "response" in result.data["result"]:
                response = result.data["result"]["response"]
                customer_question = response.get("customer_question", "")
                data_and_instructions = [
                    {
                        "instruction": item.get("instruction", ""),
                        "data": item.get("data", [])
                    }
                    for item in response.get("data_and_instructions", [])
                ]

                # Append formatted response
                formatted_results.append({
                    "customer_question": customer_question,
                    "rows": data_and_instructions
                })

        # Set the final formatted output
        self.status = Data(customer_id=self.data_objects.customer_id, customer_question=self.data_objects.customer_question, rows=formatted_results)
        return formatted_results
